CREATE TABLE `property_financials` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`uuid` CHAR(36) NOT NULL,`property_id` BIGINT UNSIGNED NOT NULL,`asking_price` DECIMAL(24,2) NULL,`currency` CHAR(3) NOT NULL DEFAULT 'IDR',`negotiable` BOOLEAN NOT NULL DEFAULT FALSE,`annual_property_tax` DECIMAL(24,2) NULL,`monthly_maintenance` DECIMAL(24,2) NULL,`monthly_utility_cost` DECIMAL(24,2) NULL,`monthly_service_charges` DECIMAL(24,2) NULL,`rental_yield` DECIMAL(8,4) NULL,`annual_rental_income` DECIMAL(24,2) NULL,`capital_growth` DECIMAL(8,4) NULL,`investment_rating` ENUM('A','B','C','D','E','NOT_RATED') NOT NULL DEFAULT 'NOT_RATED',`created_by` CHAR(36) NULL,`updated_by` CHAR(36) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE KEY `property_financials_uuid_key` (`uuid`),UNIQUE KEY `property_financials_property_id_key` (`property_id`),KEY `property_financials_currency_rating_idx` (`currency`,`investment_rating`),CONSTRAINT `property_financials_property_fk` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `property_financials_nonnegative_check` CHECK ((`asking_price` IS NULL OR `asking_price`>=0) AND (`annual_property_tax` IS NULL OR `annual_property_tax`>=0) AND (`monthly_maintenance` IS NULL OR `monthly_maintenance`>=0) AND (`monthly_utility_cost` IS NULL OR `monthly_utility_cost`>=0) AND (`monthly_service_charges` IS NULL OR `monthly_service_charges`>=0) AND (`annual_rental_income` IS NULL OR `annual_rental_income`>=0) AND (`rental_yield` IS NULL OR `rental_yield`>=0) AND (`capital_growth` IS NULL OR `capital_growth`>=0))) ENGINE=InnoDB;
CREATE TABLE `property_features` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`uuid` CHAR(36) NOT NULL,`property_id` BIGINT UNSIGNED NOT NULL,`pet_friendly` BOOLEAN NOT NULL DEFAULT FALSE,`child_friendly` BOOLEAN NOT NULL DEFAULT FALSE,`wheelchair_accessible` BOOLEAN NOT NULL DEFAULT FALSE,`elderly_friendly` BOOLEAN NOT NULL DEFAULT FALSE,`smoking_allowed` BOOLEAN NOT NULL DEFAULT FALSE,`events_allowed` BOOLEAN NOT NULL DEFAULT FALSE,`rental_allowed` BOOLEAN NOT NULL DEFAULT TRUE,`created_by` CHAR(36) NULL,`updated_by` CHAR(36) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE KEY `property_features_uuid_key` (`uuid`),UNIQUE KEY `property_features_property_id_key` (`property_id`),CONSTRAINT `property_features_property_fk` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE `property_security` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`uuid` CHAR(36) NOT NULL,`property_id` BIGINT UNSIGNED NOT NULL,`security_guard` BOOLEAN NOT NULL DEFAULT FALSE,`cctv` BOOLEAN NOT NULL DEFAULT FALSE,`access_control` BOOLEAN NOT NULL DEFAULT FALSE,`gated_community` BOOLEAN NOT NULL DEFAULT FALSE,`smart_lock` BOOLEAN NOT NULL DEFAULT FALSE,`alarm_system` BOOLEAN NOT NULL DEFAULT FALSE,`created_by` CHAR(36) NULL,`updated_by` CHAR(36) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE KEY `property_security_uuid_key` (`uuid`),UNIQUE KEY `property_security_property_id_key` (`property_id`),CONSTRAINT `property_security_property_fk` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE `property_environment` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`uuid` CHAR(36) NOT NULL,`property_id` BIGINT UNSIGNED NOT NULL,`green_building` BOOLEAN NOT NULL DEFAULT FALSE,`solar_power` BOOLEAN NOT NULL DEFAULT FALSE,`rainwater_harvesting` BOOLEAN NOT NULL DEFAULT FALSE,`water_saving` BOOLEAN NOT NULL DEFAULT FALSE,`green_certification` VARCHAR(200) NULL,`created_by` CHAR(36) NULL,`updated_by` CHAR(36) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE KEY `property_environment_uuid_key` (`uuid`),UNIQUE KEY `property_environment_property_id_key` (`property_id`),CONSTRAINT `property_environment_property_fk` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
